import java.util.Scanner;

public class Main {
    static long mod_pow(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        final int MOD = 1000000007;

        if (k == 0) {
            System.out.println(mod_pow(p, p - 1, MOD));
            return;
        }
        if (k == 1) {
            System.out.println(mod_pow(p, p, MOD));
            return;
        }

        boolean[] visited = new boolean[p + 1];
        int len = 1;
        long i = k;
        visited[1] = true;

        while (!visited[(int) i]) {
            visited[(int) i] = true;
            i = (i * k) % p;
            len++;
        }

        long tot = (p - 1) / len;
        System.out.println(mod_pow(p, (int) tot, MOD));
    }
}
